id PVXGet(id obj, NSString *key) { if(!obj)return nil; @try{return [obj valueForKey:key];} @catch(NSException *e){return nil;} }
BOOL PVXHook(Class cls, SEL sel, IMP repl, IMP *original) {
 if(!cls||!sel||!repl)return NO; Method m=class_getInstanceMethod(cls,sel); if(!m)return NO;
 typedef void(*HookFn)(Class,SEL,IMP,IMP*); HookFn hook=(HookFn)dlsym(RTLD_DEFAULT,"MSHookMessageEx");
 if(!hook){void *h=dlopen("/usr/lib/libsubstrate.dylib",RTLD_NOW); if(h)hook=(HookFn)dlsym(h,"MSHookMessageEx");}
 if(hook){hook(cls,sel,repl,original);return YES;}
 IMP old=method_getImplementation(m); if(original)*original=old;
 if(!class_addMethod(cls,sel,repl,method_getTypeEncoding(m))) method_setImplementation(class_getInstanceMethod(cls,sel),repl);
 return YES;
}
