static UIViewController *PVXTop(UIViewController *c){while(c){if(c.presentedViewController&&!c.presentedViewController.isBeingDismissed){c=c.presentedViewController;continue;}if([c isKindOfClass:UINavigationController.class]){c=((UINavigationController*)c).visibleViewController;continue;}if([c isKindOfClass:UITabBarController.class]){c=((UITabBarController*)c).selectedViewController;continue;}break;}return c;}
UIViewController *PVXPresenter(void){UIWindow *best=nil;for(UIScene *scene in UIApplication.sharedApplication.connectedScenes){if(![scene isKindOfClass:UIWindowScene.class]||scene.activationState!=UISceneActivationStateForegroundActive)continue;for(UIWindow *w in ((UIWindowScene*)scene).windows){if(w.hidden||w.alpha<0.01||!w.rootViewController)continue;if(!best||w.windowLevel>best.windowLevel||w.isKeyWindow)best=w;}}return PVXTop(best.rootViewController);}
void PVXAlert(NSString *title,NSString *message){dispatch_async(dispatch_get_main_queue(),^{UIViewController *p=PVXPresenter();if(!p)return;UIAlertController *a=[UIAlertController alertControllerWithTitle:title message:message preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"确定" style:UIAlertActionStyleDefault handler:nil]];[p presentViewController:a animated:YES completion:nil];});}
void PVXOpenDownloads(void){dispatch_async(dispatch_get_main_queue(),^{if(PVXBrowser())PVXShowDownloads();else PVXAlert(@"PyVideo",@"原插件尚未加载，请确认已启用 PyVideo 并重新打开 Safari。");});}
static NSURL *PVXHTTP(id v){NSURL *u=[v isKindOfClass:NSURL.class]?v:([v isKindOfClass:NSString.class]?[NSURL URLWithString:v]:nil);return ([u.scheme.lowercaseString isEqual:@"https"]||[u.scheme.lowercaseString isEqual:@"http"])&&u.host.length?u:nil;}
static NSURL *PVXPlayerURL(id context){NSMutableArray *q=[NSMutableArray array];if(context)[q addObject:context];NSHashTable *seen=[NSHashTable hashTableWithOptions:NSPointerFunctionsObjectPointerPersonality];for(NSUInteger n=0;n<q.count&&n<40;n++){id o=q[n];if([seen containsObject:o])continue;[seen addObject:o];NSURL *u=PVXHTTP(o);if(u)return u;if([o isKindOfClass:AVURLAsset.class])return PVXHTTP([(AVURLAsset*)o URL]);if([o isKindOfClass:NSDictionary.class]){for(NSString *k in @[@"url",@"URL",@"sourceURL",@"asset",@"player",@"currentItem",@"playerController",@"playerViewController"]){id x=o[k];if(x&&x!=NSNull.null)[q addObject:x];}continue;}for(NSString *k in @[@"player",@"currentItem",@"asset",@"playerController",@"playerViewController",@"contentURL"]){id x=PVXGet(o,k);if(x&&x!=o)[q addObject:x];}}return nil;}
static BOOL PVXActiveCandidateURL(NSString *url,NSDictionary *candidate,NSString *page){if(![url isKindOfClass:NSString.class]||url.length>16384||[url isEqual:page])return NO;NSURL *u=PVXHTTP(url);if(!u)return NO;NSString *protocol=[candidate[@"protocol"] isKindOfClass:NSString.class]?candidate[@"protocol"]:@"",*mime=[candidate[@"mime"] isKindOfClass:NSString.class]?candidate[@"mime"]:@"";NSString *x=[url.lowercaseString stringByAppendingFormat:@" %@",mime.lowercaseString];return [protocol isEqual:@"hls"]||[protocol isEqual:@"dash"]||[protocol isEqual:@"video"]||[x containsString:@"video/"]||[x containsString:@"mpegurl"]||[x containsString:@".m3u8"]||[x containsString:@".mpd"]||[x containsString:@".mp4"]||[x containsString:@".m4v"]||[x containsString:@".webm"]||[x containsString:@".mov"];}
static NSDictionary *PVXChosenPlayingCandidate(NSURL *u,NSDictionary *active,NSArray *items){NSString *page=active[@"page"]?:@"";for(NSDictionary *item in items){if(u&&[item[@"url"] isEqual:u.absoluteString])return item;for(NSDictionary *source in item[@"sources"])if(u&&[source[@"url"] isEqual:u.absoluteString]){NSMutableDictionary *copy=[item mutableCopy];copy[@"url"]=u.absoluteString;copy[@"sources"]=@[source];return copy;}}
 for(NSDictionary *candidate in active[@"sourceCandidates"]){NSString *url=candidate[@"url"];if(!PVXActiveCandidateURL(url,candidate,page))continue;for(NSDictionary *item in items){if([item[@"url"] isEqual:url])return item;for(NSDictionary *source in item[@"sources"])if([source[@"url"] isEqual:url]){NSMutableDictionary *copy=[item mutableCopy];copy[@"url"]=url;copy[@"sources"]=@[source];return copy;}}NSMutableDictionary *fresh=[@{ @"kind":@"video", @"url":url, @"sources":@[@{@"url":url,@"height":@0}], @"protocol":candidate[@"protocol"]?:@"video", @"mime":candidate[@"mime"]?:@"", @"sourceKind":@"active-network", @"title":active[@"title"]?:@"当前播放视频", @"poster":@"", @"page":page, @"frame":active[@"frame"]?:page, @"documentID":active[@"documentID"]?:@"" } mutableCopy];return fresh;}
 return nil;}
static void PVXSubmitPlaying(NSURL *u,NSDictionary *active){WKWebView *w=PVXCollectionWebView();if(!w){w=PVXCurrentWebView();if(w)PVXSetCollectionWebView(w);}if(!w){PVXAlert(@"无法下载当前视频",@"原始 Safari 页面已关闭。");return;}NSDictionary *chosen=PVXChosenPlayingCandidate(u,active,PVXCollectedMedia(@"video"));if(chosen){PVXSubmitMedia(chosen,^(NSDictionary *task,NSString *error){if(error.length||!task)PVXAlert(@"下载未提交",error?:@"没有生成任务回执");else PVXAlert(@"请求已写入下载队列",@"可在下载管理中查看后台接收及进度。完成后由你选择导出到相册或文件，不会自动保存相册。");});return;}if([active[@"blob"] boolValue]||([active[@"blobURL"] isKindOfClass:NSString.class]&&[active[@"blobURL"] length])){PVXExportActiveRuntime(^(BOOL started){if(started)PVXAlert(@"正在提取当前视频",@"播放器提供的是 Blob/MSE 数据，已开始逐段写入下载任务；完成后会出现在下载列表。");else PVXAlert(@"当前视频仍未捕获",@"已重新检查当前播放器，但没有可用上游媒体源或可读取的 Blob 数据。");});return;}PVXRefreshCollection();PVXAlert(@"正在重新采集当前影片",@"影片的原始媒体源尚未确认，请稍后再次下载；不会选择网页中的其他影片。");}
